  const [loadingOutlines, setLoadingOutlines] = useState(false);
  const [savingOutline, setSavingOutline] = useState(false);
  const [editingOutlineId, setEditingOutlineId] = useState<number | null>(null);

  useEffect(() => {
    const loadAllData = async () => {
      setIsLoadingOnMount(true);
      try {
        await Promise.all([fetchBooks(), fetchVerses(), fetchAdminEmail(), fetchDashboardStats(), fetchUsers(), fetchContactMessages(), fetchVerseSongSeries(), fetchVerseSongs()]);
        setMessage('✅ All data loaded successfully');
        setTimeout(() => setMessage(''), 3000);
      } catch (error) { console.error('Error loading data:', error); setMessage('❌ Error loading data'); }
      finally { setIsLoadingOnMount(false); }
    };
    loadAllData();
  }, []);
  const fetchAdminEmail = async () => { try { const res = await fetch('/api/auth/session'); if (res.ok) { const data = await res.json(); if (data.admin) setAdminEmail(data.admin.email); } } catch (e) { console.error(e); } };
  const fetchBooks = async () => { try { const res = await fetch('/api/bible-books?full=true'); if (!res.ok) throw new Error(`Failed: ${res.status}`); const data = await res.json(); const mappedBooks = Array.isArray(data) ? data.map((book: any) => ({ id: book.id, book_number: book.book_number, name: book.name_english || 'Unknown Book', abbreviation: book.abbreviation_english || '', testament: book.testament || '', total_chapters: book.total_chapters || 0 })) : []; setBooks(mappedBooks); } catch (e) { console.error(e); setBooks([]); } };
  const fetchVerses = async () => { try { const res = await fetch('/api/bible-verses?recent=10'); if (!res.ok) throw new Error(`Failed: ${res.status}`); const data = await res.json(); const versesList = Array.isArray(data.verses) ? data.verses : []; setVerses(versesList); if (!chapter) setFilteredVerses(versesList); } catch (e) { console.error(e); } };
  const fetchDashboardStats = async () => { setLoadingStats(true); try { const res = await fetch('/api/admin/dashboard-stats'); if (res.ok) setDashboardStats(await res.json()); } catch (e) { console.error(e); } finally { setLoadingStats(false); } };
  const fetchUsers = async (search = userSearch, status = userStatusFilter) => { setLoadingUsers(true); try { const params = new URLSearchParams({ search, status }); const res = await fetch(`/api/admin-users?${params}`); if (res.ok) { const data = await res.json(); setAllUsersData(data); setUsers(data.users || []); setActiveSessions(data.activeSessions || []); } } catch (e) { console.error(e); } finally { setLoadingUsers(false); } };
  const handleUserAction = async (userId: string, action: string) => { if (action === 'delete' && !confirm('Are you sure you want to delete this user?')) return; try { const res = await fetch('/api/admin-users', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId, action }) }); if (res.ok) { setMessage(`✅ User ${action}d successfully`); await fetchUsers(); } } catch (e) { setMessage('❌ Error: ' + (e instanceof Error ? e.message : String(e))); } setTimeout(() => setMessage(''), 3000); };
  const fetchContactMessages = async () => { try { const res = await fetch('/api/contact'); if (res.ok) { const msg = await res.json(); setContactMessages(Array.isArray(msg) ? msg : []); } } catch (e) { console.error(e); } };
  const fetchVerseSongSeries = async () => { try { const res = await fetch('/api/verse-song-series'); if (res.ok) setVerseSongSeries(await res.json()); } catch (e) { console.error(e); } };
  const fetchVerseSongs = async () => { try { const res = await fetch('/api/verse-songs'); if (res.ok) setVerseSongs(await res.json()); } catch (e) { console.error(e); } };
  // FIXED: generic loaders used by all other sections (same endpoints as original)
  const bookIdFor = () => books.find(b => b.name === selectedBook)?.id;
  const fetchPrayerPassages = async () => { if (!selectedBook || !chapter) return; setLoadingPrayerPassages(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/verse-prayers?bookId=${id}&chapter=${chapter}`); if (res.ok) setPrayerPassages(await res.json()); } catch (e) { console.error(e); } finally { setLoadingPrayerPassages(false); } };
  const fetchBookIntroductions = async () => { if (!selectedBook) return; setLoadingBookIntros(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/book-introductions?bookId=${id}`); if (res.ok) { const data = await res.json(); setBookIntroductions(data ? [data] : []); } } catch (e) { console.error(e); } finally { setLoadingBookIntros(false); } };
  const fetchChapterIntroductions = async () => { if (!selectedBook || !chapter) return; setLoadingChapterIntros(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/chapter-introductions?bookId=${id}&chapter=${chapter}`); if (res.ok) { const data = await res.json(); setChapterIntroductions(data ? [data] : []); } } catch (e) { console.error(e); } finally { setLoadingChapterIntros(false); } };
  const fetchBookCommentaries = async () => { if (!selectedBook) return; setLoadingBookCommentaries(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/book-commentaries?bookId=${id}`); if (res.ok) { const data = await res.json(); setBookCommentaries(data ? [data] : []); } } catch (e) { console.error(e); } finally { setLoadingBookCommentaries(false); } };
  const fetchChapterCommentaries = async () => { if (!selectedBook || !chapter) return; setLoadingChapterCommentaries(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/chapter-commentaries?bookId=${id}&chapter=${chapter}`); if (res.ok) { const data = await res.json(); setChapterCommentaries(data ? [data] : []); } } catch (e) { console.error(e); } finally { setLoadingChapterCommentaries(false); } };
  const fetchVerseCommentaries = async () => { if (!selectedBook || !chapter) return; setLoadingVerseCommentaries(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/verse-commentaries?bookId=${id}&chapter=${chapter}`); if (res.ok) setVerseCommentaries(await res.json()); } catch (e) { console.error(e); } finally { setLoadingVerseCommentaries(false); } };
  const fetchBookClosingPrayers = async () => { if (!selectedBook) return; setLoadingBookClosingPrayers(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/book-prayers?bookId=${id}`); if (res.ok) { const data = await res.json(); setBookClosingPrayers(data ? [data] : []); } } catch (e) { console.error(e); } finally { setLoadingBookClosingPrayers(false); } };
  const fetchChapterClosingPrayers = async () => { if (!selectedBook || !chapter) return; setLoadingChapterClosingPrayers(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/chapter-prayers?bookId=${id}&chapter=${chapter}`); if (res.ok) { const data = await res.json(); setChapterClosingPrayers(data ? [data] : []); } } catch (e) { console.error(e); } finally { setLoadingChapterClosingPrayers(false); } };
  const fetchOutlines = async () => { if (!selectedBook) return; setLoadingOutlines(true); try { const id = bookIdFor(); if (!id) return; const params = new URLSearchParams({ book_id: String(id), language: outlineLanguage }); if (outlineType === 'chapter' && chapter) params.append('chapter', chapter); const res = await fetch(`/api/outlines?${params}`); if (res.ok) setOutlines(await res.json()); } catch (e) { console.error(e); } finally { setLoadingOutlines(false); } };
  const fetchBookTheologicalInsights = async () => { if (!selectedBook) return; setLoadingBookTheologicalInsights(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/book-theological-insights?book_id=${id}`); if (res.ok) { const data = await res.json(); setBookTheologicalInsights(data); if (data) { setBookTheologicalInsightEn(data.english_insight || ''); setBookTheologicalInsightLu(data.luganda_insight || ''); } } } catch (e) { console.error(e); } finally { setLoadingBookTheologicalInsights(false); } };
  const fetchTheologicalInsights = async () => { if (!selectedBook || !chapter) return; setLoadingTheologicalInsights(true); try { const id = bookIdFor(); if (!id) return; const res = await fetch(`/api/verse-theological-insights?bookId=${id}&chapter=${chapter}`); if (res.ok) setTheologicalInsights(await res.json()); } catch (e) { console.error(e); } finally { setLoadingTheologicalInsights(false); } };

  // Generic save helper (same pattern as original: POST or PUT with id when editing)
  const postOrPut = async (url: string, payload: any, editingId: any) => {
    const res = await fetch(url, { method: editingId ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(editingId ? { ...payload, id: editingId } : payload) });
    if (!res.ok) { const d = await res.json().catch(() => ({})); throw new Error(d.error || d.message || `Failed: ${res.status}`); }
    return res;
  };
  const flash = (msg: string) => { setMessage(msg); setTimeout(() => setMessage(''), 3000); };
  // Commentary
  const saveBookCommentary = async () => { if (!selectedBook || (!bookCommentaryEn.trim() && !bookCommentaryLu.trim())) return flash('❌ Please select a book and enter commentary text'); setSavingBookCommentary(true); try { const id = bookIdFor(); if (!id) throw new Error('Book not found'); await postOrPut('/api/book-commentaries', { book_id: id, english_commentary: bookCommentaryEn, luganda_commentary: bookCommentaryLu }, editingBookCommentaryId); flash(editingBookCommentaryId ? '✅ Book commentary updated!' : '✅ Book commentary saved!'); setBookCommentaryEn(''); setBookCommentaryLu(''); setEditingBookCommentaryId(null); await fetchBookCommentaries(); } catch (e) { flash('❌ Error: ' + (e instanceof Error ? e.message : String(e))); } finally { setSavingBookCommentary(false); } };
  const editBookCommentary = (c: any) => { setBookCommentaryEn(c.english_commentary || ''); setBookCommentaryLu(c.luganda_commentary || ''); setEditingBookCommentaryId(c.id); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const deleteBookCommentary = async (id: number) => { if (!confirm('Delete this book commentary?')) return; try { const res = await fetch(`/api/book-commentaries?id=${id}`, { method: 'DELETE' }); if (!res.ok) throw new Error(`Failed: ${res.status}`); flash('✅ Book commentary deleted!'); await fetchBookCommentaries(); } catch (e) { flash('❌ Error: ' + (e instanceof Error ? e.message : String(e))); } };
  const cancelEditBookCommentary = () => { setEditingBookCommentaryId(null); setBookCommentaryEn(''); setBookCommentaryLu(''); };
  const saveChapterCommentary = async () => { if (!selectedBook || !chapter || (!chapterCommentaryEn.trim() && !chapterCommentaryLu.trim())) return flash('❌ Please select book, chapter and enter commentary text'); setSavingChapterCommentary(true); try { const id = bookIdFor(); if (!id) throw new Error('Book not found'); await postOrPut('/api/chapter-commentaries', { book_id: id, chapter: parseInt(chapter), english_commentary: chapterCommentaryEn, luganda_commentary: chapterCommentaryLu }, editingChapterCommentaryId); flash('✅ Chapter commentary saved!'); setChapterCommentaryEn(''); setChapterCommentaryLu(''); setEditingChapterCommentaryId(null); await fetchChapterCommentaries(); } catch (e) { flash('❌ Error: ' + (e instanceof Error ? e.message : String(e))); } finally { setSavingChapterCommentary(false); } };
  const editChapterCommentary = (c: any) => { setChapterCommentaryEn(c.english_commentary || ''); setChapterCommentaryLu(c.luganda_commentary || ''); setEditingChapterCommentaryId(c.id); window.scrollTo({ top: 0, behavior: 'smooth' }); };
