  const cancelEditChapterCommentary = () => { setEditingChapterCommentaryId(null); setChapterCommentaryEn(''); setChapterCommentaryLu(''); };
  const saveVerseCommentary = async () => { if (!selectedBook || !chapter || !verseNumber || (!verseCommentaryEn.trim() && !verseCommentaryLu.trim())) return flash('❌ Please select verse and enter commentary text'); setSavingVerseCommentary(true); try { const id = bookIdFor(); if (!id) throw new Error('Book not found'); await postOrPut('/api/verse-commentaries', { book_id: id, chapter: parseInt(chapter), verse_number: parseInt(verseNumber), commentary_text: verseCommentaryEn, luganda_commentary_text: verseCommentaryLu }, editingVerseCommentaryId); flash('✅ Verse commentary saved!'); setVerseCommentaryEn(''); setVerseCommentaryLu(''); setVerseNumber(''); setEditingVerseCommentaryId(null); await fetchVerseCommentaries(); } catch (e) { flash('❌ Error: ' + (e instanceof Error ? e.message : String(e))); } finally { setSavingVerseCommentary(false); } };
  const editVerseCommentary = (c: any) => { setVerseNumber(String(c.verse_number)); setVerseCommentaryEn(c.commentary_text || ''); setVerseCommentaryLu(c.luganda_commentary_text || ''); setEditingVerseCommentaryId(c.id); window.scrollTo({ top: 0, behavior: 'smooth' }); };
